   134	// killPinnedMarkedProcess signals pid only through a pidfd opened on it,
   135	// after the environment read through that same pinned process still holds
   136	// entry.
   137	func killPinnedMarkedProcess(pid int, entry []byte) error {
   138		fd, err := unix.PidfdOpen(pid, 0)
   139		if errors.Is(err, unix.ESRCH) {
   140			return nil
   141		}
   142		if err != nil {
   143			return fmt.Errorf("process %d could not be pinned: %w", pid, err)
   144		}
   145		defer unix.Close(fd)
   146		// The pidfd names one process for its lifetime; if pid was reused before
   147		// it was opened, the new process does not carry this run's entry.
   148		marked, err := reviewProcessMarked(pid, entry)
   149		if reviewProcessGoneErr(err) || err == nil && !marked {
   150			return nil
   151		}
   152		if err != nil {
   153			return fmt.Errorf("process %d could not be inspected: %w", pid, err)
   154		}
   155		if err := unix.PidfdSendSignal(fd, unix.SIGKILL, nil, 0); err != nil && !errors.Is(err, unix.ESRCH) {
   156			return fmt.Errorf("process %d could not be ended: %w", pid, err)
   157		}
   158		return nil
   159	}
