   161	func reviewProcessMarked(pid int, entry []byte) (bool, error) {
   162		environ, err := os.ReadFile(filepath.Join("/proc", strconv.Itoa(pid), "environ"))
   163		if err != nil {
   164			return false, err
   165		}
   166		for _, kv := range bytes.Split(environ, []byte{0}) {
   167			if bytes.Equal(kv, entry) {
   168				return true, nil
   169			}
   170		}
   171		return false, nil
   172	}
