   198	func reviewProcessZombie(pid int) (bool, error) {
   199		raw, err := os.ReadFile(filepath.Join("/proc", strconv.Itoa(pid), "stat"))
   200		if err != nil {
   201			return false, err
   202		}
   203		// The state follows the parenthesised command name.
   204		if i := bytes.LastIndexByte(raw, ')'); i >= 0 && i+2 < len(raw) {
   205			return raw[i+2] == 'Z', nil
   206		}
   207		return false, fmt.Errorf("process %d state is unreadable", pid)
   208	}
