   257	// ResolveDelegationRef finds the one attempt ref names (R11).
   258	func ResolveDelegationRef(attempts []DelegationAttempt, ref string) (DelegationAttempt, error) {
   259		ref = strings.TrimSpace(ref)
   260		if ref == "" {
   261			return DelegationAttempt{}, &ErrDelegationRefUnknown{}
   262		}
   263		// An identifier is exact and wins over a label or a session prefix.
   264		for _, a := range attempts {
   265			if a.AttemptID == ref || containsString(a.Runs, ref) {
   266				return a, nil
   267			}
   268		}
   269		var matched []DelegationAttempt
   270		for _, a := range attempts {
   271			hit := a.Label == ref
   272			if !hit && len(ref) >= 6 {
   273				for _, session := range a.sessions {
   274					if strings.HasPrefix(session, ref) {
   275						hit = true
   276					}
   277				}
   278			}
   279			if hit {
   280				matched = append(matched, a)
   281			}
   282		}
   283		switch len(matched) {
   284		case 0:
   285			return DelegationAttempt{}, &ErrDelegationRefUnknown{}
   286		case 1:
   287			return matched[0], nil
   288		}
   289		candidates := make([]string, 0, len(matched))
   290		for _, a := range matched {
   291			name := a.AttemptID
   292			if a.Label != "" {
   293				name += " (" + a.Label + ", " + a.State + ")"
   294			}
   295			candidates = append(candidates, name)
   296		}
   297		return DelegationAttempt{}, &ErrDelegationRefAmbiguous{Candidates: candidates}
   298	}

