   185	// orphanReservations lists the reservations left without a receipt or a
   186	// marker, older than reviewOrphanReservationAge, and
   187	// says which reservations or receipts it could not read (review round 3, N3).
   188	func (s Store) orphanReservations(now time.Time) ([]DelegatedReviewAttempt, []string, error) {
   189		base := filepath.Join(s.Root, reviewAttemptDir)
   190		dirs, err := os.ReadDir(base)
   191		if errors.Is(err, os.ErrNotExist) {
   192			return nil, nil, nil
   193		}
   194		if err != nil {
   195			return nil, nil, err
   196		}
   197		markers, markerLost, err := s.ListDelegationActive()
   198		if err != nil {
   199			return nil, nil, err
   200		}
   201		if len(markerLost) > 0 {
   202			// An unreadable marker may be a live attempt's: nothing is known to
   203			// have no marker (review round 6, N1).
   204			return nil, append([]string{"abandoned reservations cannot be determined while an active marker is unreadable"}, markerLost...), nil
   205		}
   206		marked := map[string]bool{}
   207		for _, m := range markers {
   208			marked[m.AttemptID] = true
   209		}
   210		runs, runLost, err := s.ReadReviewRuns("")
   211		if err != nil {
   212			return nil, nil, err
   213		}
   214		if len(runLost) > 0 {
   215			// Without the whole run history nothing is known to have no run.
   216			return nil, append([]string{"abandoned reservations cannot be determined while the run history is incomplete"}, runLost...), nil
   217		}
   218		// A recorded run does not finish an attempt, its receipt does: a
   219		// reservation whose run was recorded without a receipt still blocks and
   220		// is released with that run (review round 5, N3).
   221		_ = runs
   222		var out []DelegatedReviewAttempt
   223		var lost []string
   224		budget := reviewReadBudget(nil)
   225		for _, d := range dirs {
   226			if !d.IsDir() {
   227				continue
   228			}
   229			entries, err := os.ReadDir(filepath.Join(base, d.Name()))
   230			if err != nil {
   231				lost = append(lost, "the reservations in "+d.Name()+" could not be listed: "+err.Error())
   232				continue
   233			}
   234			for _, e := range entries {
   235				if IsPublisherStaging(e.Name()) || !strings.HasSuffix(e.Name(), ".json") || strings.HasSuffix(e.Name(), ".result.json") {
   236					continue
   237				}
   238				var a DelegatedReviewAttempt
   239				if err := readLedgerJSONBudgetIn(s.fsys(), filepath.Join(base, d.Name(), e.Name()), &a, budget); err != nil {
   240					lost = append(lost, "the reservation "+d.Name()+"/"+e.Name()+" could not be read: "+err.Error())
   241					continue
   242				}
   243				if a.AttemptID != attemptIdentity(a) {
   244					lost = append(lost, "the reservation "+d.Name()+"/"+e.Name()+" does not match its identity")
   245					continue
   246				}
   247				if marked[a.AttemptID] {
   248					continue
   249				}
   250				if _, err := os.Lstat(attemptReceiptPath(s.Root, a)); err == nil {
   251					continue
   252				} else if !errors.Is(err, os.ErrNotExist) {
   253					lost = append(lost, "the receipt of "+a.AttemptID+" could not be inspected: "+err.Error())
   254					continue
   255				}
   256				at, err := time.Parse(time.RFC3339Nano, a.ReservedAt)
   257				if err != nil || now.Sub(at) < reviewOrphanReservationAge {
   258					continue
   259				}
   260				out = append(out, a)
   261			}
   262		}
   263		return out, lost, nil
   264	}
