  1961			meta, _, ok := strings.Cut(strings.TrimSuffix(string(out), "\x00"), "\t")
  1962			fields := strings.Fields(meta)
  1963			if !ok || len(fields) < 3 {
  1964				continue // not in the sealed commit
  1965			}
  1966			mode, object := fields[0], fields[2]
  1967			info, lerr := os.Lstat(filepath.Join(root, filepath.FromSlash(rel)))
  1968			if lerr != nil {
  1969				return rel + " (it cannot be inspected: " + lerr.Error() + ")"
  1970			}
  1971			switch mode {
  1972			case "120000":
  1973				target, rerr := os.Readlink(filepath.Join(root, filepath.FromSlash(rel)))
  1974				if info.Mode()&os.ModeSymlink == 0 || rerr != nil || gitBlobID("sha1", []byte(target)) != object && gitBlobID("sha256", []byte(target)) != object {
