   253					lost = append(lost, "the receipt of "+a.AttemptID+" could not be inspected: "+err.Error())
   254					continue
   255				}
   256				at, err := time.Parse(time.RFC3339Nano, a.ReservedAt)
   257				if err != nil || now.Sub(at) < reviewOrphanReservationAge {
   258					continue
   259				}
   260				out = append(out, a)
   261			}
   262		}
   263		return out, lost, nil
   264	}
