    28	// killProcessGroup ends whatever the adapter left running.
    29	func killProcessGroup(cmd *exec.Cmd) error {
    30		if cmd.Process == nil {
    31			return nil
    32		}
    33		err := syscall.Kill(-cmd.Process.Pid, syscall.SIGKILL)
    34		if errors.Is(err, syscall.ESRCH) {
    35			return nil
    36		}
    37		if err != nil {
    38			return err
    39		}
    40		return verifyReviewProcessGroup(cmd.Process.Pid)
